test('factory English signs and glowing exhibit borders remain local, preserve content and reuse six bounded coloured lights',async()=>{
 const THREE=await import('three'),{default:factoryKit}=await import('../app/factory-kit.js'),{default:createArt}=await import('../app/interior-art.js'),{buildingDisplayName,factoryName}=await import('../lib/factory-style.ts'),{bloomSource}=await import('../app/scene-effects.js');const original={id:'factory-id',title:'資訊工廠',specialType:'factory'},before=JSON.stringify(original);assert.equal(buildingDisplayName(original),factoryName);assert.equal(JSON.stringify(original),before);assert.equal(buildingDisplayName({title:'拾月序',specialType:'none'}),'拾月序');
 for(const lowDetail of [false,true]){const k=factoryKit({lowDetail}),parent=new THREE.Group(),rim=k.exhibitGlow(parent),core=rim.getObjectByName('factory-exhibit-emissive-rim');assert.equal(rim.userData.interactiveCue,true);assert.ok(bloomSource(core.material));assert.ok(core.material.color.r<=1.51);rim.traverse(o=>{if(o.material?.transparent){assert.equal(bloomSource(o.material),false);assert.ok(o.material.opacity<=.10);}});const scene=new THREE.Scene(),art=createArt({scene,mode:'factory',lowDetail}),words=[];art.root.traverse(o=>{if(o.userData.neonText){words.push(o.userData.neonText);assert.ok(/^[A-Z ]+$/.test(o.userData.neonText));}if(o.userData.sign)assert.ok(!/[\u3400-\u9fff]/.test(o.userData.sign.title));});assert.ok(['INFORMATION FACTORY','OPEN LATE','STORIES','HIDDEN BAR'].every(word=>words.includes(word)));assert.equal(art.lightSources.length,6);assert.ok(art.lightSources.slice(4).every(l=>l.distance<=7&&l.power<=14));art.dispose();k.dispose();}
});


test('factory external stair layers carry warm yellow lamps on actual treads and landings while the entrance and bridges stay clear',async()=>{
 const THREE=await import('three'),{default:factoryKit}=await import('../app/factory-kit.js'),{default:factoryStairs}=await import('../app/factory-stairs.js'),{factoryStairFlights,factoryOutdoorBlocked}=await import('../lib/factory-style.ts'),{walkable,findRoute}=await import('../lib/navigation.ts'),{worldPosition,bridgeSegments}=await import('../lib/archipelago.ts');
 assert.equal(factoryStairFlights.length,4);for(const lowDetail of [false,true]){const k=factoryKit({lowDetail}),parent=new THREE.Group(),sources=[],a=factoryStairs({parent,kit:k,sources});parent.updateMatrixWorld(true);assert.equal(a.root.userData.levels.length,3);assert.ok(a.mounts.length>=20);assert.equal(a.mounts.length,sources.filter(s=>s.kind==='stair').length);assert.ok(a.root.getObjectByName('factory-rear-upper-catwalk'));
  for(const lamp of a.mounts){const mount=lamp.userData.stairMount,position=lamp.getWorldPosition(new THREE.Vector3());assert.ok(Math.abs(position.y-mount.deckHeight)<1e-5,'lamp feet rest on the stair or platform');const source=lamp.getObjectByName('factory-yellow-stair-light-source');assert.ok(source.material.color.r>source.material.color.g&&source.material.color.g>source.material.color.b);assert.equal(source.castShadow,false);assert.equal(source.material.userData.bloom,true);if(mount.kind==='flight'){const f=factoryStairFlights.find(f=>f.id===mount.id),height=f.y0+(f.y1-f.y0)*(mount.step+1)/f.steps;assert.ok(Math.abs(position.y-height)<1e-5);assert.ok(Math.abs(Math.abs(position.x-f.x)-(f.width/2+.04))<1e-5);}}
  let triangles=0;parent.traverse(o=>{if(o.geometry){for(const v of o.geometry.attributes.position.array)assert.ok(Number.isFinite(v));if(o.isMesh)triangles+=(o.geometry.index?.count??o.geometry.attributes.position.count)/3;}});assert.ok(triangles<17000);k.dispose();
 }
 const project=publicBuildingDefaults.find(p=>p.specialType==='factory'),q=worldPosition(project),to={x:q.x,z:q.z+footprint(project)+1.3},path=findRoute({x:0,z:15},to,publicBuildingDefaults);assert.ok(path.length>10);assert.ok(path.every(p=>walkable(p.x,p.z,publicBuildingDefaults)));assert.equal(factoryOutdoorBlocked(0,7.3),false);assert.equal(factoryOutdoorBlocked(7.55,0),true);assert.equal(factoryOutdoorBlocked(9.2,0),false);for(const {a,b}of bridgeSegments()){const c={x:(a.x+b.x)/2,z:(a.z+b.z)/2};assert.equal(walkable(c.x,c.z,publicBuildingDefaults),true);}
});
